'use strict';

/**
 * Thrown when CSV input is malformed. `line` and `column` are 1-based;
 * columns count UTF-16 code units. `code` identifies the kind of problem so
 * callers can branch without matching on the message.
 */
class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line
   * @param {number} column
   * @param {'UNCLOSED_QUOTE'|'INVALID_AFTER_QUOTE'|'DUPLICATE_HEADER'|'FIELD_COUNT_MISMATCH'} code
   */
  constructor(message, line, column, code) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

module.exports = { CsvError };

