  if (isFirst && line.charCodeAt(0) === BOM) {
    texts[0] = quote(texts[0]);
    return texts.join(delimiter);
  }
  return line;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

