'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse } = require('../src/csv');

describe('parse: input validation', () => {
  for (const [label, value] of [
    ['number', 42],
    ['null', null],
    ['undefined', undefined],
    ['array', ['a,b']],
    ['Buffer', Buffer.from('a,b')],
    ['String object', new String('a,b')], // eslint-disable-line no-new-wrappers
  ]) {
    it(`throws TypeError when text is a ${label}`, () => {
      assert.throws(() => parse(value), TypeError);
    });
  }

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
  });

  it('throws TypeError when options is not an object', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', [',']), TypeError);
  });

  it('throws TypeError for non-boolean header or skipEmptyLines', () => {
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { header: 1 }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 'true' }), TypeError);
  });

  it('ignores options it does not use, such as eol', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });

  it('does not modify the options object', () => {
    const options = Object.freeze({ delimiter: ';', header: true, skipEmptyLines: true });
    assert.deepEqual(parse('a;b\n1;2\n', options), [{ a: '1', b: '2' }]);
    assert.deepEqual(options, { delimiter: ';', header: true, skipEmptyLines: true });
  });
});

describe('parse: delimiter option', () => {
  it('splits on , by default', () => {
    assert.deepEqual(parse('a,b,c'), [['a', 'b', 'c']]);
  });

  for (const delimiter of [';', '\t', '|', ' ', 'x', '§']) {
    it(`splits on ${JSON.stringify(delimiter)} and treats commas as data`, () => {
      const text = ['a,1', 'b', `"c${delimiter}d"`].join(delimiter);
      assert.deepEqual(parse(text, { delimiter }), [['a,1', 'b', `c${delimiter}d`]]);
    });
  }

  for (const [label, delimiter] of [
    ['empty string', ''],
    ['two characters', ',,'],
    ['double quote', '"'],
    ['CR', '\r'],
    ['LF', '\n'],
    ['number', 44],
    ['null', null],
    ['astral character (two code units)', '\u{1F600}'],
  ]) {
    it(`throws TypeError for a delimiter that is a ${label}`, () => {
      assert.throws(() => parse('a', { delimiter }), TypeError);
    });
  }
});

describe('parse: records and line breaks', () => {
  it('accepts CRLF, LF and CR, mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('does not start a record after one trailing line break', () => {
    assert.deepEqual(parse('a,b\r\n'), [['a', 'b']]);
    assert.deepEqual(parse('a,b\n'), [['a', 'b']]);
    assert.deepEqual(parse('a,b\r'), [['a', 'b']]);
  });

  it('returns [""] for each other empty line', () => {
    assert.deepEqual(parse('a\n\nb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('\r\n'), [['']]);
    assert.deepEqual(parse('\n\n'), [[''], ['']]);
  });

  it('reads LF followed by CR as two line breaks, not one', () => {
    assert.deepEqual(parse('\n\r'), [[''], ['']]);
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  });

  it('reads CR followed by CRLF as two line breaks', () => {
    assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
  });

  it('keeps records with different field counts when header is off', () => {
    assert.deepEqual(parse('a,b\nc\n,,'), [['a', 'b'], ['c'], ['', '', '']]);
  });

  it('keeps empty fields at the start, middle and end of a record', () => {
    assert.deepEqual(parse(','), [['', '']]);
    assert.deepEqual(parse(',a,,b,'), [['', 'a', '', 'b', '']]);
    assert.deepEqual(parse('a,\n'), [['a', '']]);
  });
});

describe('parse: skipEmptyLines', () => {
  it('skips empty lines anywhere in the input', () => {
    assert.deepEqual(parse('\n\na\n\n\nb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
    assert.deepEqual(parse('\r\n\r\r\n', { skipEmptyLines: true }), []);
  });

  it('keeps a line holding "" and a line holding only whitespace', () => {
    assert.deepEqual(parse('""\n\n \n', { skipEmptyLines: true }), [[''], [' ']]);
  });

  it('keeps a line holding only a delimiter', () => {
    assert.deepEqual(parse('\n,\n', { skipEmptyLines: true }), [['', '']]);
  });

  it('has no effect when false', () => {
    assert.deepEqual(parse('a\n\nb', { skipEmptyLines: false }), [['a'], [''], ['b']]);
  });
});

describe('parse: quoted fields', () => {
  it('keeps delimiters, CR and LF inside quotes literally', () => {
    assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh"'), [['a,b', 'c\nd', 'e\r\nf', 'g\rh']]);
  });

  it('reads "" inside quotes as one "', () => {
    assert.deepEqual(parse('"a""b",""""'), [['a"b', '"']]);
  });

  it('reads "" alone as an empty field', () => {
    assert.deepEqual(parse('""'), [['']]);
    assert.deepEqual(parse('"",""'), [['', '']]);
  });

  it('treats " inside an unquoted field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c"\n5"'), [['a"b', 'c"'], ['5"']]);
  });

  it('treats a field starting with a space then " as unquoted', () => {
    assert.deepEqual(parse(' "a", b'), [[' "a"', ' b']]);
  });

  it('allows a quoted field at the end of input with no line break', () => {
    assert.deepEqual(parse('a,"b"'), [['a', 'b']]);
  });
});

describe('parse: whitespace, BOM and unicode', () => {
  it('never trims fields', () => {
    assert.deepEqual(parse(' a , b \t,\t'), [[' a ', ' b \t', '\t']]);
  });

  it('ignores a leading byte order mark', () => {
    assert.deepEqual(parse('﻿a,b\n'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
