const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv');

function expectCsvError(text, options, { line, column, code }) {
  assert.throws(
    () => parse(text, options),
    (error) => {
      assert.ok(error instanceof CsvError, `expected CsvError, got ${error && error.name}`);
      assert.deepEqual({ line: error.line, column: error.column, code: error.code }, { line, column, code });
      return true;
    },
  );
}

describe('CsvError', () => {
  it('is an Error subclass named CsvError with line, column and code', () => {
    const error = new CsvError('Bad input', 3, 7, 'UNCLOSED_QUOTE');
