'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Result of a whole-input parse, comparable with `outcomeOfChunks`. */
function outcomeOfParse(text, options) {
  try {
    return { records: parse(text, options) };
  } catch (error) {
    if (!(error instanceof CsvError)) throw error;
    return { error: { line: error.line, column: error.column, code: error.code } };
  }
}

/** Feeds `chunks` to a streaming parser and collects everything it returns. */
function outcomeOfChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  try {
    for (const chunk of chunks) records.push(...parser.write(chunk));
    records.push(...parser.end());
    return { records };
  } catch (error) {
    if (!(error instanceof CsvError)) throw error;
    return { error: { line: error.line, column: error.column, code: error.code } };
  }
}

/** Every way to cut `text` into two and three chunks, plus one code unit per chunk. */
function* splits(text) {
  const n = text.length;
  yield [text];
  yield ['', text, ''];
  yield Array.from(text);
  for (let i = 0; i <= n; i++) {
    yield [text.slice(0, i), text.slice(i)];
    for (let j = i; j <= n; j++) yield [text.slice(0, i), text.slice(i, j), text.slice(j)];
  }
}

const CORPUS = [
  '',
  'a,b\r\nc,d\r\n',
  'a\rb\nc\r\nd',
  '\r\n\r\n\n\r',
  'a\r\r\nb\n\n',
  '"a,b","c""d"\r\n"",""""\n',
  '"line\r\nbreak","x\ry\nz"\r\n',
  'a"b,c"\n"q"',
  '﻿"a",b\n',
  '﻿﻿,﻿',
  ' a , "b" ,c ',
  '"\u{1F600}",é\n',
  '"unclosed\r\nfield',
  'x,"a"b\r\n',
  '"a""',
  'a,b\n\n1,2\n',
  'a,b\n1,2,3\n"4"x',
  '"h\r\n1",h2\r\n1,2\r\n',
  'a,a,"x',
  'h\n\n\nv\n',
];

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

describe('createParser: chunk boundaries never change the result', () => {
  for (const options of OPTION_SETS) {
    it(`matches parse for every 2- and 3-way split with options ${JSON.stringify(options)}`, () => {
      for (const text of CORPUS) {
        const expected = outcomeOfParse(text, options);
