'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const csv = require('../src/csv');

const { parse, createParser, stringify } = csv;

/** Deterministic PRNG (mulberry32) so failures reproduce from the seed. */
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Every character the format treats specially, plus ones that are easy to
// mishandle: BOM, astral characters, combining marks, NUL, tab.
const ALPHABET = ['a', 'Z', '0', ' ', ',', ';', '\t', '|', '"', '\r', '\n', '﻿', '\u{1F600}', 'é', '\u0000'];

function randomRows(next) {
  const rows = [];
  const rowCount = Math.floor(next() * 6);
  for (let r = 0; r < rowCount; r++) {
    const row = [];
    const fieldCount = 1 + Math.floor(next() * 4);
    for (let f = 0; f < fieldCount; f++) {
      let field = '';
      // Bias towards empty and short fields, where the edge cases live.
      const length = next() < 0.25 ? 0 : Math.floor(next() * 6);
      for (let c = 0; c < length; c++) field += ALPHABET[Math.floor(next() * ALPHABET.length)];
      row.push(field);
    }
    rows.push(row);
  }
  return rows;
}

function randomChunks(text, next) {
  const chunks = [];
  let index = 0;
  while (index < text.length) {
    const size = Math.floor(next() * 4);
    chunks.push(text.slice(index, index + size));
    index += size;
  }
  return chunks;
}

function streamParse(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

const DELIMITERS = [',', ';', '\t', ' ', '|', '"'.repeat(0) || 'x', '﻿'];

describe('round trip: parse(stringify(rows)) returns rows', () => {
  for (const delimiter of DELIMITERS) {
    for (const eol of ['\r\n', '\n']) {
      for (const skipEmptyLines of [false, true]) {
        const options = { delimiter, eol, skipEmptyLines };
        it(`holds for 300 random tables with ${JSON.stringify(options)}`, () => {
          const next = random(delimiter.charCodeAt(0) * 4 + eol.length * 2 + Number(skipEmptyLines));
          for (let trial = 0; trial < 300; trial++) {
            const rows = randomRows(next);
            const text = stringify(rows, options);
            assert.deepEqual(parse(text, options), rows, `seed trial ${trial}: ${JSON.stringify(text)}`);
          }
        });
      }
    }
  }

  it('holds for the edge cases that need special quoting', () => {
    const cases = [
      [['']],
      [[''], [''], ['']],
      [['', '']],
      [['﻿']],
      [['﻿a', 'b']],
      [[' '], ['a ', ' b']],
      [['"'], ['""'], ['"a"']],
      [['\r'], ['\n'], ['\r\n'], ['\n\r']],
    ];
    for (const rows of cases) {
      for (const skipEmptyLines of [false, true]) {
        assert.deepEqual(parse(stringify(rows), { skipEmptyLines }), rows);
      }
    }
  });
});

describe('round trip: streaming parser on stringify output', () => {
  it('returns the original rows for random chunkings', () => {
    const next = random(42);
    for (let trial = 0; trial < 300; trial++) {
      const rows = randomRows(next);
      const options = { delimiter: next() < 0.5 ? ',' : ';', eol: next() < 0.5 ? '\r\n' : '\n' };
      const text = stringify(rows, options);
      assert.deepEqual(streamParse(randomChunks(text, next), options), rows, JSON.stringify(text));
    }
  });
});

describe('round trip: header mode', () => {
  it('turns objects into CSV and back', () => {
    const header = ['id', 'note, with comma', 'empty', '__proto__'];
    const objects = [
      { id: '1', 'note, with comma': 'line\nbreak', empty: '', __proto__: null },
      { id: '2', 'note, with comma': ' padded ', empty: '' },
    ];
    const text = stringify(objects, { header });
    const parsed = parse(text, { header: true });
    assert.equal(parsed.length, 2);
    assert.deepEqual(Object.keys(parsed[0]), header);
    assert.equal(parsed[0]['note, with comma'], 'line\nbreak');
    assert.equal(parsed[1]['note, with comma'], ' padded ');
    assert.equal(Object.getOwnPropertyDescriptor(parsed[0], '__proto__').value, '');
  });

  it('gives [] back for a header with no rows', () => {
    assert.deepEqual(parse(stringify([], { header: ['a', 'b'] }), { header: true }), []);
  });

  it('gives the same objects whether parsed whole or streamed', () => {
    const header = ['k', 'v'];
    const objects = [];
    for (let i = 0; i < 50; i++) objects.push({ k: `key${i}`, v: `"v${i}"\r\n` });
    const text = stringify(objects, { header });
    const chunks = randomChunks(text, random(7));
    assert.deepEqual(streamParse(chunks, { header: true }), parse(text, { header: true }));
    assert.deepEqual(parse(text, { header: true }), objects);
  });
});

describe('module surface and README examples', () => {
  it('exports exactly parse, createParser, stringify and CsvError', () => {
    assert.deepEqual(Object.keys(csv).sort(), ['CsvError', 'createParser', 'parse', 'stringify']);
    assert.equal(require('..'), csv);
  });

  it('matches the parse examples', () => {
    assert.deepEqual(parse('name,qty\r\n"Widget, large",3\r\n'), [['name', 'qty'], ['Widget, large', '3']]);
    assert.deepEqual(parse('name,qty\nWidget,3\n', { header: true }), [{ name: 'Widget', qty: '3' }]);
    assert.deepEqual(parse('a;b\n\n1;2', { delimiter: ';', skipEmptyLines: true }), [['a', 'b'], ['1', '2']]);
  });

  it('matches the stringify examples', () => {
    assert.equal(stringify([['a', 'b c'], ['x,y', 'say "hi"']]), 'a,b c\r\n"x,y","say ""hi"""\r\n');
    assert.equal(
      stringify([{ id: 1, name: 'Ada' }, { id: 2 }], { header: ['id', 'name'], eol: '\n' }),
      'id,name\n1,Ada\n2,\n',
    );
  });
});

