'use strict';

const { CsvError } = require('./errors');
const { resolveParseOptions, describe } = require('./options');

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// FIELD_START: nothing of the current field has been consumed.
// AFTER_QUOTE: the previous code unit was a `"` inside a quoted field; it is
// either the closing quote or the first half of an escaped `""`.
const FIELD_START = 0;
const UNQUOTED = 1;
const QUOTED = 2;
const AFTER_QUOTE = 3;

/**
 * Incremental CSV state machine. Every code unit is examined exactly once, and
 * all state that must survive a chunk boundary (partial field, pending CR,
 * pending quote) lives on the instance, so the split points never change the
 * result. `parse` is this class fed a single chunk.
