  constructor(options) {
    const { delimiter, header, skipEmptyLines } = resolveParseOptions(options);
    this.delimiter = delimiter.charCodeAt(0);
    this.skipEmptyLines = skipEmptyLines;

    // In header mode, `seenNames` is non-null only while the header record is
    // being read, so duplicates are caught as soon as the repeated field ends.
    this.headerMode = header;
    this.headerNames = null;
    this.seenNames = header ? new Set() : null;

    this.state = FIELD_START;
    this.fields = [];
    this.parts = []; // pieces of the current field that ended a chunk or preceded a `""`
    this.segmentStart = 0; // chunk index where the not-yet-saved piece of the field begins
    this.recordEmpty = true; // no code unit of the current record consumed yet
    this.afterCR = false; // previous code unit was a CR, so an LF now completes a CRLF

    this.started = false;
    this.chunkOffset = 0; // absolute offset of the current chunk's first code unit
    this.line = 1;
    this.lineOffset = 0; // absolute offset of the current line's first code unit
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.quoteLine = 1;
    this.quoteColumn = 1;

    this.output = [];
  }

  column(index) {
    return this.chunkOffset + index - this.lineOffset + 1;
  }

  write(chunk) {
    const length = chunk.length;
    let index = 0;
    if (!this.started && length > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) {
        // The BOM is not part of the data, so column 1 is the code unit after it.
        index = 1;
        this.lineOffset = 1;
      }
    }

    while (index < length) {
      switch (this.state) {
        case FIELD_START:
          index = this.fieldStart(chunk, index);
          break;
        case UNQUOTED:
          index = this.unquoted(chunk, index);
          break;
        case QUOTED:
          index = this.quoted(chunk, index);
          break;
        default:
          index = this.afterQuote(chunk, index);
      }
    }

    if ((this.state === UNQUOTED || this.state === QUOTED) && this.segmentStart < length) {
      this.parts.push(chunk.slice(this.segmentStart));
    }
    this.segmentStart = 0;
    this.chunkOffset += length;
    return this.takeOutput();
  }

  end() {
    switch (this.state) {
      case QUOTED:
        throw new CsvError(
          'Quoted field is never closed',
          this.quoteLine,
          this.quoteColumn,
          'UNCLOSED_QUOTE',
        );
      case UNQUOTED:
      case AFTER_QUOTE:
        this.endField(this.joinParts());
        this.endRecord();
        break;
      default:
        // An empty pending record means the input was empty or ended with a
        // line break, which does not start another record.
        if (!this.recordEmpty) {
          this.endField('');
          this.endRecord();
        }
    }
    return this.takeOutput();
  }

  fieldStart(chunk, index) {
    const code = chunk.charCodeAt(index);
    if (this.afterCR) {
      this.afterCR = false;
      if (code === LF) {
        this.lineOffset = this.chunkOffset + index + 1;
        return index + 1;
      }
    }

    if (this.recordEmpty) {
      // Later fields get their start position from delimiterAt.
      this.recordLine = this.line;
      this.fieldLine = this.line;
      this.fieldColumn = this.column(index);
    }

    if (code === QUOTE) {
      this.recordEmpty = false;
      this.quoteLine = this.fieldLine;
      this.quoteColumn = this.fieldColumn;
      this.state = QUOTED;
      this.segmentStart = index + 1;
      return this.quoted(chunk, index + 1);
    }
    if (code === this.delimiter) {
      this.recordEmpty = false;
      this.endField('');
      this.delimiterAt(index);
      return index + 1;
    }
    if (code === CR || code === LF) {
      if (!this.recordEmpty || !this.skipEmptyLines) {
        this.endField('');
        this.endRecord();
      }
      this.recordBreak(code, index);
      return index + 1;
    }
    this.recordEmpty = false;
    this.state = UNQUOTED;
    this.segmentStart = index;
    return this.unquoted(chunk, index + 1);
  }

  unquoted(chunk, index) {
    const length = chunk.length;
    const delimiter = this.delimiter;
    for (; index < length; index++) {
      const code = chunk.charCodeAt(index);
      if (code === delimiter) {
        this.endField(this.takeValue(chunk, index));
        this.delimiterAt(index);
        return index + 1;
      }
      if (code === CR || code === LF) {
        this.endField(this.takeValue(chunk, index));
        this.endRecord();
        this.recordBreak(code, index);
        return index + 1;
      }
    }
    return index;
  }

  quoted(chunk, index) {
    const length = chunk.length;
    let afterCR = this.afterCR;
    for (; index < length; index++) {
      const code = chunk.charCodeAt(index);
      if (code === QUOTE) {
        if (index > this.segmentStart) this.parts.push(chunk.slice(this.segmentStart, index));
        this.afterCR = false;
        this.state = AFTER_QUOTE;
        return index + 1;
      }
      if (code === CR) {
        this.line++;
        this.lineOffset = this.chunkOffset + index + 1;
        afterCR = true;
      } else if (code === LF) {
        if (!afterCR) this.line++;
        this.lineOffset = this.chunkOffset + index + 1;
        afterCR = false;
      } else {
        afterCR = false;
      }
    }
    this.afterCR = afterCR;
    return index;
  }

  afterQuote(chunk, index) {
    const code = chunk.charCodeAt(index);
    if (code === QUOTE) {
      // Escaped quote: keep the second `"` as the first unit of the next piece.
      this.state = QUOTED;
      this.segmentStart = index;
      return this.quoted(chunk, index + 1);
    }
    if (code === this.delimiter) {
      this.endField(this.joinParts());
      this.delimiterAt(index);
      return index + 1;
    }
    if (code === CR || code === LF) {
      this.endField(this.joinParts());
      this.endRecord();
      this.recordBreak(code, index);
      return index + 1;
    }
    throw new CsvError(
      `Expected a delimiter, line break or end of input after a closing quote, found ${JSON.stringify(chunk[index])}`,
      this.line,
      this.column(index),
      'INVALID_AFTER_QUOTE',
    );
  }

  /** Records a CR or LF (outside quotes) that has just ended a record. */
  recordBreak(code, index) {
    this.line++;
    this.lineOffset = this.chunkOffset + index + 1;
    this.afterCR = code === CR;
    this.state = FIELD_START;
  }

  takeValue(chunk, end) {
    const piece = chunk.slice(this.segmentStart, end);
    if (this.parts.length === 0) return piece;
    this.parts.push(piece);
    return this.joinParts();
  }

  joinParts() {
    const value = this.parts.length === 1 ? this.parts[0] : this.parts.join('');
    this.parts.length = 0;
    return value;
  }

  endField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
          'DUPLICATE_HEADER',
        );
      }
      this.seenNames.add(value);
    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    this.recordEmpty = true;

    if (!this.headerMode) {
      this.output.push(fields);
      return;
    }
    if (this.headerNames === null) {
      this.headerNames = fields;
      this.seenNames = null;
      return;
    }
    const names = this.headerNames;
    if (fields.length !== names.length) {
      throw new CsvError(
        `Expected ${names.length} field${names.length === 1 ? '' : 's'} to match the header, found ${fields.length}`,
        this.recordLine,
        1,
        'FIELD_COUNT_MISMATCH',
      );
    }
    this.output.push(toObject(names, fields));
  }

  takeOutput() {
    const records = this.output;
    this.output = [];
    return records;
  }
}

function toObject(names, fields) {
  const record = {};
  for (let k = 0; k < names.length; k++) {
    if (names[k] === '__proto__') {
      // Plain assignment would call the prototype setter and drop the value.
      Object.defineProperty(record, '__proto__', {
        value: fields[k],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    } else {
      record[names[k]] = fields[k];
    }
  }
